```python
def three_sum(nums: list) -> list:
    n = len(nums)
    seen = set()
    out = []
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if nums[i] + nums[j] + nums[k] == 0:
                    trip = tuple(sorted([nums[i], nums[j], nums[k]]))
                    if trip not in seen:
                        seen.add(trip)
                        out.append(list(trip))
    out.sort()
    return out
